import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"The Object-Arrow Kernel","description":"","frontmatter":{"title":"The Object-Arrow Kernel","type":"adr","date":"2026-09-11T00:00:00.000Z","status":"accepted","status_note":"Accepted — one semantic world; arrows are the only primitive."},"headers":[],"relativePath":"handl/project/adrs/0106-object-arrow-kernel.md","filePath":"vendored/handl/project/adrs/0106-object-arrow-kernel.md"}`),a={name:`handl/project/adrs/0106-object-arrow-kernel.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0106-the-object-arrow-kernel" tabindex="-1">ADR-0106: The Object-Arrow Kernel <a class="header-anchor" href="#adr-0106-the-object-arrow-kernel" aria-label="Permalink to “ADR-0106: The Object-Arrow Kernel”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>One semantic world.</strong> Values, objects, types and arrows share one value space; there is no separate type namespace.</li><li><strong><code>sym()</code> / <code>sym(A)</code> is the nominal identity primitive</strong> — names are values, and nominal typing is symbol identity.</li><li><strong>Arrows are the fundamental computational primitive.</strong> There is no binding model and no mutation.</li><li><strong>Products and composition are the structural core</strong>; <code>do</code> is sugar over composition.</li><li><strong>Dimensions <code>&lt;&gt;</code> specialize any value or arrow</strong>, and generic objects use the same machinery.</li><li><strong>Graded arrows</strong> carry effects in the grade, not in special forms.</li><li><strong>Algebra, capabilities and ordering</strong> use the same objects and arrows — no interface/trait/impl layer.</li><li><strong>Proofs, refinements and dependent types are ordinary objects/arrows.</strong></li><li><strong>Polymorphism and Liskov are <code>sym</code>-based</strong>; higher-order arrows and combinators need no new kernel primitive.</li><li><strong>Expected-type inference and runtime/static convergence</strong> follow from the same arrow semantics.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The kernel had several semantic worlds — values, types, objects — plus a binding model, so every new feature added a primitive. One world plus arrows makes the surface derivable: products, dimensions, grades and proofs are compositions, not kernel cases.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Separate type/object namespaces</strong> — the split is what multiplied primitives.</li><li><strong>A binding model or mutation</strong> — both are derivable from arrows.</li><li><strong>An interface/trait/impl layer</strong> — <code>sym</code> and arrows express the same thing.</li><li><strong>Add a primitive per feature</strong> — features compose instead.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>The kernel stays small; inference does more of the work.</li><li>Errors surface as type/arrow mismatches rather than special-case checks.</li><li>Performance depends on lowering arrows well, not on kernel shortcuts.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>kernel/</code> — <code>Term</code>, <code>Value</code>, <code>sym</code> and the arrow constructors.</li><li><code>crates/handl-kit-data-canonical/data/</code> — the data that lowers to arrows.</li><li>Conformance tests in the kernel and host crates.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+The full semantics, conformance notes and the serializable representation: +<a href="./../design/0106-object-arrow-kernel.html"><code>design/0106-object-arrow-kernel.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};